150	<script>
151	import router from "@system.router"
152	import storage from "@system.storage"
153	import { getWeather } from "../../common/services"
154	import { getThemeSync, setTheme } from "../../common/theme"
155	import { getCached, setCache } from "../../common/cache"
156	import { regions } from "../../common/cities"
157	
158	function pad(value) {
159	  return value < 10 ? "0" + value : "" + value
160	}
161	
162	var CITY_STORAGE_KEY = "infoWeatherCity"
163	
164	export default {
165	  private: {
166	    isDark: false,
167	    themeButtonText: "深色模式",
168	    modeLabel: "浅色",
169	    currentTime: "--:--",
170	    selectedCity: "北京",
171	    showCityPicker: false,
172	    pickerLevel: 0,
173	    pickerTitle: "选择地区",
174	    pickerList: [],
175	    regionLabel: "",
176	    provinceLabel: "",
177	    selectedRegionIdx: -1,
178	    selectedProvinceIdx: -1,
179	    expandedAlertIdx: -1,
180	    weatherInfo: {
181	      title: "北京",
182	      subtitle: "正在获取天气...",
183	      message: "--°C",
184	      details: [],
185	      detailsExtra: [],
186	      indexes: [],
187	      forecasts: [],
188	      alerts: []
189	    }
190	  },
191	
192	  onInit() {
193	    this.isDark = getThemeSync()
194	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
195	    this.modeLabel = this.isDark ? "深色" : "浅色"
196	    this.updateClock()
197	    this.loadSavedCity()
198	  },
199	
200	  onShow() {
201	    this.updateClock()
202	  },
203	
204	  updateClock() {
205	    var now = new Date()
206	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
207	  },
208	
209	  toggleTheme() {
210	    this.isDark = !this.isDark
211	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
212	    this.modeLabel = this.isDark ? "深色" : "浅色"
213	    setTheme(this.isDark)
214	  },
215	
216	  goHome() {
217	    router.push({ uri: "pages/index" })
218	  },
219	
220	  goNews() {
221	    router.back()
222	  },
223	
224	  goExpress() {
225	    router.push({ uri: "pages/express" })
226	  },
227	
228	  loadSavedCity() {
229	    var self = this
230	    storage.get({
231	      key: CITY_STORAGE_KEY,
232	      success: function (data) {
233	        if (data) {
234	          self.selectedCity = data
235	        }
236	        self.loadWeatherData()
237	      },
238	      fail: function () {
239	        self.loadWeatherData()
240	      }
241	    })
242	  },
243	
244	  saveCity(city) {
245	    storage.set({
246	      key: CITY_STORAGE_KEY,
247	      value: city
248	    })
249	  },
250	
251	  toggleAlert(idx) {
252	    this.expandedAlertIdx = this.expandedAlertIdx === idx ? -1 : idx
253	  },
254	
255	  openCityPicker() {
256	    this.pickerLevel = 0
257	    this.pickerTitle = "选择地区"
258	    this.regionLabel = ""
259	    this.provinceLabel = ""
260	    this.selectedRegionIdx = -1
261	    this.selectedProvinceIdx = -1
262	    this.pickerList = []
263	    this.showCityPicker = true
264	  },
265	
266	  pickRegion(idx) {
267	    this.selectedRegionIdx = idx
268	    this.regionLabel = regions[idx].name
269	    this.pickerTitle = regions[idx].name
270	    var names = []
271	    var provs = regions[idx].provinces
272	    for (var i = 0; i < provs.length; i++) {
273	      names.push(provs[i].name)
274	    }
275	    this.pickerList = names
276	    this.pickerLevel = 1
277	  },
278	
279	  pickProvince(idx) {
280	    if (this.selectedRegionIdx < 0 || idx < 0) return
281	    var provs = regions[this.selectedRegionIdx].provinces
282	    if (idx >= provs.length) return
283	    this.selectedProvinceIdx = idx
284	    this.provinceLabel = provs[idx].name
285	    this.pickerTitle = this.provinceLabel
286	    this.pickerList = provs[idx].cities
287	    this.pickerLevel = 2
288	  },
289	
290	  pickCity(idx) {
291	    if (idx < 0 || idx >= this.pickerList.length) return
292	    this.selectedCity = this.pickerList[idx]
293	    this.saveCity(this.selectedCity)
294	    this.showCityPicker = false
295	    this.loadWeatherData()
296	  },
297	
298	  pickerBack() {
299	    if (this.pickerLevel === 2) {
300	      this.pickerLevel = 1
301	      this.pickerTitle = this.regionLabel
302	      var provs = regions[this.selectedRegionIdx].provinces
303	      var names = []
304	      for (var i = 0; i < provs.length; i++) {
305	        names.push(provs[i].name)
306	      }
307	      this.pickerList = names
308	    } else if (this.pickerLevel === 1) {
309	      this.pickerLevel = 0
310	      this.pickerTitle = "选择地区"
311	      this.regionLabel = ""
312	      this.provinceLabel = ""
313	      this.selectedRegionIdx = -1
314	      this.pickerList = []
315	    } else {
316	      this.showCityPicker = false
317	    }
318	  },
319	
320	  jumpToRegion() {
321	    this.pickerLevel = 0
322	    this.pickerTitle = "选择地区"
323	    this.regionLabel = ""
324	    this.provinceLabel = ""
325	    this.selectedRegionIdx = -1
326	    this.pickerList = []
327	  },
328	
329	  jumpToProvince() {
330	    if (this.selectedRegionIdx < 0) return
331	    this.pickerLevel = 1
332	    this.pickerTitle = this.regionLabel
333	    var provs = regions[this.selectedRegionIdx].provinces
334	    var names = []
335	    for (var i = 0; i < provs.length; i++) {
336	      names.push(provs[i].name)
337	    }
338	    this.pickerList = names
339	  },
340	
341	  loadWeatherData() {
342	    var city = this.selectedCity
343	    var cacheKey = "weather_" + city
344	    var cached = getCached(cacheKey)
345	    if (cached) {
346	      this.weatherInfo = cached
347	      return
348	    }
349	    getWeather(city).then((info) => {
350	      setCache(cacheKey, info, 10 * 60 * 1000)
351	      this.weatherInfo = info
352	      this.expandedAlertIdx = -1
353	    })
354	  }
355	}
356	</script>
