function request(options) {
  const url = options.url
  const method = options.method || "GET"
  const responseType = options.responseType || "json"

  return new Promise((resolve, reject) => {
    let isCompleted = false

    // Set a manual 60s timeout
    const timeoutId = setTimeout(() => {
      if (!isCompleted) {
        isCompleted = true
        reject(new Error("Timeout"))
      }
    }, 60000)

    fetch.fetch({
      url: url,
      method: method,
      header: options.header || {},
      responseType: responseType,
      success(res) {
        if (isCompleted) return
        isCompleted = true
        clearTimeout(timeoutId)

        const code = res.code || res.statusCode

        let data = res.data
        if (responseType === "json" && typeof data === "string") {
          data = parseData(data)
        }

        if (code >= 200 && code < 300) {
          resolve(data)
        } else if (data && typeof data === "object") {
          // fallback: 响应体存在且是对象，直接使用
          resolve(data)
        } else {
          reject(new Error("HTTP " + code))
        }
      },
      fail(data, code) {
        if (isCompleted) return
        isCompleted = true
        clearTimeout(timeoutId)

        reject(new Error("Fetch failed: " + code))
      }
    })
  })
}

input.new_string:
function request(options) {
  const url = options.url
  const method = options.method || "GET"
  const responseType = options.responseType || "json"

  return new Promise((resolve, reject) => {
    let isCompleted = false

    // Set a manual 60s timeout
    const timeoutId = setTimeout(() => {
      if (!isCompleted) {
        isCompleted = true
        reject(new Error("Timeout"))
      }
    }, 60000)

    fetch.fetch({
      url: url,
      method: method,
      header: options.header || {},
      responseType: responseType,
      success(res) {
        if (isCompleted) return
        isCompleted = true
        clearTimeout(timeoutId)

        const code = res.code || res.statusCode

        // 兼容：先尝试 res.data，再尝试 res.result（不同 quickapp 实现可能不同）
        let data = res.data !== undefined ? res.data : res.result

        // 无论如何都尝试 parse，防止 responseType json 未生效
        if (typeof data === "string") {
          data = parseData(data)
        }

        if (code >= 200 && code < 300) {
          resolve(data)
        } else if (data && typeof data === "object" && Object.keys(data).length > 0) {
          // fallback: 响应体存在且是非空对象，直接使用
          resolve(data)
        } else {
          reject(new Error("HTTP " + code))
        }
      },
      fail(data, code) {
        if (isCompleted) return
        isCompleted = true
        clearTimeout(timeoutId)

        reject(new Error("Fetch failed: " + code))
      }
    })
  })
}

