54	    this.loading = true
55	    fetchText(this.url)
56	      .then((data) => {
57	        this.loading = false
58	        if (data) {
59	          // Detect CAPTCHA / human verification pages
60	          var lower = data.toLowerCase()
61	          var isCaptcha = lower.indexOf("verify") !== -1 ||
62	                          lower.indexOf("captcha") !== -1 ||
63	                          lower.indexOf("人机验证") !== -1 ||
64	                          lower.indexOf("滑动验证") !== -1 ||
