96	  parseHTML(html) {
97	    if (!html) return ""
98	
99	    // 1. Pre-cleanup
100	    let content = html.replace(/<head[^>]*>([\s\S]*?)<\/head>/gi, "")
101	                      .replace(/<header[^>]*>([\s\S]*?)<\/header>/gi, "")
102	                      .replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, "")
103	                      .replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, "")
104	                      .replace(/<nav[^>]*>([\s\S]*?)<\/nav>/gi, "")
105	                      .replace(/<footer[^>]*>([\s\S]*?)<\/footer>/gi, "")
106	
107	    // 2. Extract nested content: find opening tag, then count div depth to find matching close
108	    function extractNested(html, openPattern, label) {
109	      let openMatch = openPattern.exec(html)
110	      if (!openMatch) {
111	        return null
112	      }
113	      let openEnd = openMatch.index + openMatch[0].length
114	      let depth = 1
115	      let pos = openEnd
116	      let openCount = 0
117	      let closeCount = 0
118	      // Make tag search case-insensitive
119	      let lowerHtml = html.toLowerCase()
120	      while (depth > 0 && pos < html.length) {
121	        let nextOpen = lowerHtml.indexOf("<div", pos)
122	        let nextClose = lowerHtml.indexOf("</div>", pos)
123	
124	        let candidates = []
125	        if (nextOpen !== -1) candidates.push({ pos: nextOpen, type: "open" })
126	        if (nextClose !== -1) candidates.push({ pos: nextClose, type: "close" })
127	
128	        if (candidates.length === 0) break
129	        candidates.sort(function(a, b) { return a.pos - b.pos })
130	        let first = candidates[0]
131	
132	        if (first.type === "open") {
133	          depth++
134	          openCount++
135	          pos = first.pos + 4
136	        } else {
137	          depth--
138	          closeCount++
139	          if (depth === 0) {
140	            let extracted = html.substring(openEnd, first.pos)
141	            return extracted
142	          }
143	          pos = first.pos + 6
144	        }
145	      }
146	      let fallback = html.substring(openEnd)
147	      return fallback
148	    }
